window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a47730f9e283216"]={"versions": [{"id": "FIG-2a47730f9e283216", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation des sequenziellen Kontrollflusses innerhalb des Funktionsbausteins <code>E2E_P07mForward()</code> des AUTOSAR E2E-Profils 7m. Es visualisiert den Teilschritt „Write DataID“ als Bestandteil der Header-Serialisierung im AUTOSAR Adaptive / Classic Platform E2E-Protokollstack (PRS_E2EProtocol).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Aktivität:</strong> <code>E2E_P07mForward()</code></li>\n<li><strong>Eingangsdaten / Parameter:</strong></li>\n<li><code>ForwardStatus</code>: Statuswert zur Signalisierung des Weiterleitungszustands bzw. Fehlers (<code>E2E_P_ERROR</code>)</li>\n<li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator</li>\n<li><strong>Ausgangsdaten / Puffer:</strong></li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten E2E-Header-Daten</li>\n<li>Zieladressbereich: <code>Data[Offset+16...Offset+19]</code> (4 Bytes)</li>\n<li><strong>Knoten & Verzweigungen:</strong></li>\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Node) mit Prädikat <code>if ForwardStatus == E2E_P_ERROR</code> und den Kontrollfluss-Guards <code>[TRUE]</code> sowie <code>[FALSE]</code></li>\n<li>Zwei Aktionsknoten zur Übertragung der DataID</li>\n<li>Zusammenführungsknoten (Merge Node)</li>\n<li>Endknoten (Activity Final Node)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am initialen Kontrollknoten und führt zur Auswertung der Verzweigungsbedingung <code>if ForwardStatus == E2E_P_ERROR</code>.</li>\n<li>Im Fehlerfall (<code>[TRUE]</code>): Der Wert <code>Config-&gt;DataID + 1</code> wird als 4-Byte-Wert in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in den Pufferbereich <code>Data[Offset+16...Offset+19]</code> kopiert.</li>\n<li>Im regulären Fall (<code>[FALSE]</code>): Der Wert <code>Config-&gt;DataID</code> wird als 4-Byte-Wert in Big-Endian-Byte-Reihenfolge in denselben Pufferbereich <code>Data[Offset+16...Offset+19]</code> kopiert.</li>\n<li>Beide Pfade münden über den Zusammenführungsknoten in den finalen Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00814]</code> (Rückführbarkeit auf <code>RS_E2E_08539</code>) ist das im Diagramm definierte Verhalten für den Schritt „Write DataID“ in <code>E2E_P07mForward()</code> normativ verbindlich. Durch die gezielte Verfälschung der <code>DataID</code> (<code>Config-&gt;DataID + 1</code>) im Zustand <code>E2E_P_ERROR</code> wird sichergestellt, dass nachfolgende Empfänger beim E2E-Check einen Fehler erkennen und ungültig weitergeleitete Botschaften verwerfen. Byte-Reihenfolge (Big Endian) und Byte-Offset (+16 bis +19) müssen zwingend spezifikationskonform umgesetzt werden.</p>"}, {"id": "FIG-1545f49a11f50151", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation des sequenziellen Kontrollflusses innerhalb des Funktionsbausteins <code>E2E_P07mForward()</code> des AUTOSAR E2E-Profils 7m. Es visualisiert den Teilschritt „Write DataID“ als Bestandteil der Header-Serialisierung im AUTOSAR Adaptive / Classic Platform E2E-Protokollstack (PRS_E2EProtocol).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktion / Aktivität:</strong> <code>E2E_P07mForward()</code></li>\n<li><strong>Eingangsdaten / Parameter:</strong></li>\n<li><code>ForwardStatus</code>: Statuswert zur Signalisierung des Weiterleitungszustands bzw. Fehlers (<code>E2E_P_ERROR</code>)</li>\n<li><code>Config-&gt;DataID</code>: 4-Byte-Konfigurationsidentifikator</li>\n<li><strong>Ausgangsdaten / Puffer:</strong></li>\n<li><code>Data[]</code>: Byte-Array zur Aufnahme der serialisierten E2E-Header-Daten</li>\n<li>Zieladressbereich: <code>Data[Offset+16...Offset+19]</code> (4 Bytes)</li>\n<li><strong>Knoten & Verzweigungen:</strong></li>\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Node) mit Prädikat <code>if ForwardStatus == E2E_P_ERROR</code> und den Kontrollfluss-Guards <code>[TRUE]</code> sowie <code>[FALSE]</code></li>\n<li>Zwei Aktionsknoten zur Übertragung der DataID</li>\n<li>Zusammenführungsknoten (Merge Node)</li>\n<li>Endknoten (Activity Final Node)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am initialen Kontrollknoten und führt zur Auswertung der Verzweigungsbedingung <code>if ForwardStatus == E2E_P_ERROR</code>.</li>\n<li>Im Fehlerfall (<code>[TRUE]</code>): Der Wert <code>Config-&gt;DataID + 1</code> wird als 4-Byte-Wert in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in den Pufferbereich <code>Data[Offset+16...Offset+19]</code> kopiert.</li>\n<li>Im regulären Fall (<code>[FALSE]</code>): Der Wert <code>Config-&gt;DataID</code> wird als 4-Byte-Wert in Big-Endian-Byte-Reihenfolge in denselben Pufferbereich <code>Data[Offset+16...Offset+19]</code> kopiert.</li>\n<li>Beide Pfade münden über den Zusammenführungsknoten in den finalen Endknoten der Aktivität.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00814]</code> (Rückführbarkeit auf <code>RS_E2E_08539</code>) ist das im Diagramm definierte Verhalten für den Schritt „Write DataID“ in <code>E2E_P07mForward()</code> normativ verbindlich. Durch die gezielte Verfälschung der <code>DataID</code> (<code>Config-&gt;DataID + 1</code>) im Zustand <code>E2E_P_ERROR</code> wird sichergestellt, dass nachfolgende Empfänger beim E2E-Check einen Fehler erkennen und ungültig weitergeleitete Botschaften verwerfen. Byte-Reihenfolge (Big Endian) und Byte-Offset (+16 bis +19) müssen zwingend spezifikationskonform umgesetzt werden.</p>"}], "trans": [{"from": "FIG-2a47730f9e283216", "to": "FIG-1545f49a11f50151", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
